import { MetadataRoute } from 'next'

export default function robots(): MetadataRoute.Robots {
  return {
    rules: { userAgent: '*', allow: '/', disallow: ['/admin/', '/api/admin/'] },
    // The docs at /docs keep their own sitemap (generated by the ARC docs site).
    sitemap: ['https://www.growmax.io/sitemap.xml', 'https://www.growmax.io/docs/sitemap.xml'],
  }
}
